import{apiClient}from"./client";const getOrganizationSlug=()=>localStorage.getItem("organizationSlug")||"",getStoreRules=async()=>{var a=getOrganizationSlug();return(await apiClient.get("/admin/store-rules",{params:{organizationSlug:a}})).data},getStoreRule=async a=>{var t=getOrganizationSlug();return(await apiClient.get("/admin/store-rules/"+a,{params:{organizationSlug:t}})).data},upsertStoreRule=async(a,t)=>{var e=getOrganizationSlug();return(await apiClient.put("/admin/store-rules/"+a,t,{params:{organizationSlug:e}})).data},deleteStoreRule=async a=>{var t=getOrganizationSlug();return(await apiClient.delete("/admin/store-rules/"+a,{params:{organizationSlug:t}})).data};export{getStoreRules,getStoreRule,upsertStoreRule,deleteStoreRule};